    exports=["Motor vehicles, SUVs, and automotive components (representing over 45% of total merchandise exports)", "Electrical machinery, televisions, and electronic equipment", "Iron, steel, and flat-rolled metal products", "Industrial machinery and nuclear equipment", "Rubber tires and automotive parts", "Plastics, chemicals, and refined fuels"],
